//! Source-linear grouped K21 scalar for D15:{223,232,322}|R:2-2-2.
mod fold {
#![allow(dead_code,unused_imports)]
include!("../unaudited-codex-orbit0-filtered-k18-charge-2026-08-23/run_k18_charge.rs");
use std::collections::BTreeMap;
use std::fs::rename;
const U21:i128=400_591_699_200;
const SLICES:usize=485;
const HEADS_PER_SLICE:u64=13_824;
const IDS:[&str;3]=["D15:223|R:2-2-2","D15:232|R:2-2-2","D15:322|R:2-2-2"];

#[derive(Clone,Default)]struct Q{heads:u64,source:i128,l1:i128,p1:u64,k17:u64,piv17:u64,p2:u64,k19:u64,piv19:u64,p3:u64,k21:u64,charge:i128,hits:u64,misses:u64,peak:usize,hist:BTreeMap<(u8,u8,u8),u64>}
impl Q{fn add(&mut self,x:Q){self.heads+=x.heads;self.source+=x.source;self.l1+=x.l1;self.p1+=x.p1;self.k17+=x.k17;self.piv17+=x.piv17;self.p2+=x.p2;self.k19+=x.k19;self.piv19+=x.piv19;self.p3+=x.p3;self.k21+=x.k21;self.charge+=x.charge;self.hits+=x.hits;self.misses+=x.misses;self.peak=self.peak.max(x.peak);for(k,v)in x.hist{*self.hist.entry(k).or_default()+=v}}}
type TailPlan=Vec<(u8,[u8;12],Vec<usize>)>;
fn packet_row(r:&R8,packet:usize,a:&[u8;4],b:&[u8;4],c:&[u8;4])->Row{match packet{0=>make(r,c,a,b),1=>make(r,a,c,b),2=>make(r,a,b,c),_=>unreachable!()}}
fn worker(e:Arc<E>,start:usize,end:usize,step:usize)->[Q;3]{let mut out:[Q;3]=std::array::from_fn(|_|Q::default());let mut avail_cache:HashMap<[u8;12],Vec<usize>>=HashMap::new();let mut plan_cache:HashMap<([u8;12],u8),TailPlan>=HashMap::new();
 for ri in (start..end).step_by(step){let r=&e.records[ri];let positive=(r.coefficient as i128)*(r.size as i128);let mut terminal:HashMap<RKey,(i64,i64,u64,u64)>=HashMap::new();
  for packet in 0..3{let other:Vec<_>=(0..3).filter(|&x|x!=packet).collect();for a in &e.factor[other[0]][0]{for b in &e.factor[other[1]][0]{for c in &e.factor[packet][1]{let row15=packet_row(r,packet,a,b,c);let q=&mut out[packet];q.heads+=1;q.source-=positive;q.l1+=positive.abs();let s15=sig(&row15,&e);assert_eq!(s15.iter().map(|&x|x as usize).sum::<usize>(),9);let ps1=avail_cache.entry(s15).or_insert_with(||avail(s15,&e)).clone();let m1=ps1.len();assert!(m1>0);q.p1+=m1 as u64;q.k17+=12*m1 as u64;
    for p1 in ps1{for t1 in &e.tails[p1][0]{let s17=child_sig(s15,p1,t1,&e);assert_eq!(s17.iter().map(|&x|x as usize).sum::<usize>(),7);let ps2=avail_cache.entry(s17).or_insert_with(||avail(s17,&e)).clone();if ps2.is_empty(){continue}q.piv17+=1;q.p2+=ps2.len()as u64;q.k19+=12*ps2.len()as u64;let row17=replace(&row15,&e.anchors[p1],t1);assert_eq!(sig(&row17,&e),s17);
     let m2=ps2.len();for p2 in ps2{let key=(s17,p2 as u8);let plan=plan_cache.entry(key).or_insert_with(||{let mut z=Vec::new();for(ti,t2)in e.tails[p2][0].iter().enumerate(){let s19=child_sig(s17,p2,t2,&e);let ps3=avail(s19,&e);if !ps3.is_empty(){z.push((ti as u8,s19,ps3))}}z});for(ti,s19,ps3)in plan.iter(){q.piv19+=1;let m3=ps3.len();q.p3+=m3 as u64;*q.hist.entry((m1 as u8,m2 as u8,m3 as u8)).or_default()+=1;assert_eq!(U21%((m1*m2*m3)as i128),0);let unit=positive*U21/((m1*m2*m3)as i128);let row19=replace(&row17,&e.anchors[p2],&e.tails[p2][0][*ti as usize]);assert_eq!(sig(&row19,&e),*s19);
       for &p3 in ps3{let rkey=RKey{profile:profile(&row19,p3,&e),sig:*s19,pivot:p3 as u8,degree:2};let z=if let Some(&x)=terminal.get(&rkey){q.hits+=1;x}else{q.misses+=1;resp(&row19,*s19,p3,2,&e,&mut terminal)};assert_eq!((z.2,z.3),(12,12));assert_eq!(z.0,z.1);q.k21+=12;q.charge+=unit*(z.0 as i128)}
      }}
    }}
   }}}}
  for q in &mut out{q.peak=q.peak.max(terminal.len())}
 }
 out
}
fn hist(h:&BTreeMap<(u8,u8,u8),u64>)->String{h.iter().map(|(&(a,b,c),v)|format!("\"{}_{}_{}\":{}",a,b,c,v)).collect::<Vec<_>>().join(",")}
fn jq(name:&str,q:&Q)->String{format!(concat!("\"{}\":{{\"source_heads\":{},\"source_coefficient\":\"{}\",\"l1_source_coefficient\":\"{}\",\"p1_uses\":{},\"K17_children\":{},\"pivotable_K17_children\":{},\"p2_uses\":{},\"K19_children\":{},\"pivotable_K19_children\":{},\"p3_uses\":{},\"K21_children\":{},\"charge_scaled_U\":\"{}\"}}"),name,q.heads,q.source,q.l1,q.p1,q.k17,q.piv17,q.p2,q.k19,q.piv19,q.p3,q.k21,q.charge)}
pub fn run(){let args:Vec<_>=std::env::args().collect();let mut begin=0usize;let mut count=SLICES;let mut workers=8usize;let mut output="computations/unaudited-codex-orbit0-k21-d15-r2-2-2-charge-2026-08-24/results_k21_d15_r2_2_2.json".to_string();let mut i=1;while i<args.len(){match args[i].as_str(){"--start-slice"=>{begin=args[i+1].parse().unwrap();i+=2},"--count-slices"=>{count=args[i+1].parse().unwrap();i+=2},"--workers"=>{workers=args[i+1].parse().unwrap();i+=2},"--output"=>{output=args[i+1].clone();i+=2},_=>panic!("bad arg")}}assert!(begin<=SLICES&&count<=SLICES-begin&&(1..=8).contains(&workers));let end=begin+count;let begun=Instant::now();let e=Arc::new(parse());assert_eq!(e.records.len(),SLICES);assert!(e.piv.iter().all(|p|p.iter().map(|&x|x as usize).sum::<usize>()==4));assert!(e.tails.iter().all(|x|x[0].iter().all(|t|tsig(t,&e).iter().map(|&z|z as usize).sum::<usize>()==2)));let mut jobs=Vec::new();for w in 0..workers{let x=e.clone();jobs.push(thread::spawn(move||worker(x,begin+w,end,workers)))}let mut packets:[Q;3]=std::array::from_fn(|_|Q::default());for j in jobs{let x=j.join().unwrap();for p in 0..3{packets[p].add(x[p].clone())}}let mut z=Q::default();for q in packets.iter().cloned(){z.add(q)}assert_eq!(z.heads,count as u64*HEADS_PER_SLICE);assert_eq!(z.k17,12*z.p1);assert_eq!(z.k19,12*z.p2);assert_eq!(z.k21,12*z.p3);assert_eq!(z.hits+z.misses,z.p3);assert_eq!(z.hist.values().sum::<u64>(),z.piv19);assert_eq!(z.hist.iter().map(|((_,_,m3),v)|*m3 as u64 * *v).sum::<u64>(),z.p3);if begin==0&&count==SLICES{assert_eq!((z.heads,z.source,z.l1),(6_704_640,322_486_272,3_085_516_800));assert_eq!((z.p1,z.k17,z.piv17,z.p2,z.k19),(55_934_080,671_208_960,451_445_760,1_876_057_600,22_512_691_200));}let elapsed=begun.elapsed().as_secs_f64();let full=elapsed*SLICES as f64/count as f64;let status=if begin==0&&count==SLICES{"PASS_COMPLETE_GROUPED_D15_R_2_2_2_K21_CHARGE"}else{"PASS_BOUNDED_D15_R_2_2_2_SLICE_GATE"};let ids=IDS.iter().map(|x|format!("\"{}\"",x)).collect::<Vec<_>>().join(",");let text=format!(concat!("{{\n  \"status\":\"{}\",\n  \"scale_U\":\"{}\",\n  \"ids\":[{}],\n  \"individual_id_charges\":null,\n  \"slice_interval\":[{},{}],\n  \"workers\":{},\n  \"source_slices\":{},\n  \"source_heads\":{},\n  \"source_coefficient\":\"{}\",\n  \"l1_source_coefficient\":\"{}\",\n  \"p1_uses\":{},\n  \"K17_children\":{},\n  \"pivotable_K17_children\":{},\n  \"p2_uses\":{},\n  \"K19_children\":{},\n  \"pivotable_K19_children\":{},\n  \"p3_uses\":{},\n  \"K21_terminal_occurrences\":{},\n  \"full_occurrences\":{},\n  \"irreducible_occurrences\":{},\n  \"full_charge_scaled_U\":\"{}\",\n  \"irreducible_charge_scaled_U\":\"{}\",\n  \"m1_m2_m3_occurrence_hist\":{{{}}},\n  \"terminal_cache\":{{\"hits\":{},\"misses\":{},\"peak_keys_per_slice\":{}}},\n  \"representative_packet_diagnostics\":{{{},{},{}}},\n  \"packet_grouping_guard\":\"packet0=322, packet1=232, packet2=223 witnesses are retained, but R8 H-orbit masses permute packet labels; only the grouped three-ID scalar is source-faithful\",\n  \"sign_rule\":\"direct K15 coefficient is -positive; three response flips give +positive/(m1*m2*m3)\",\n  \"terminality\":\"anchor sum 9-4+2-4+2-4+2=3, below every K0 pivot sum 4\",\n  \"elapsed_seconds\":{:.6},\n  \"projected_full_seconds\":{:.6},\n  \"scope\":\"exact grouped three-ID scalar only; no K21 rows, K22, membership, or conjecture verdict\"\n}}\n"),status,U21,ids,begin,end,workers,count,z.heads,z.source,z.l1,z.p1,z.k17,z.piv17,z.p2,z.k19,z.piv19,z.p3,z.k21,z.k21,z.k21,z.charge,z.charge,hist(&z.hist),z.hits,z.misses,z.peak,jq("packet0_322_witness_class",&packets[0]),jq("packet1_232_witness_class",&packets[1]),jq("packet2_223_witness_class",&packets[2]),elapsed,full);let tmp=format!("{}.tmp",output);std::fs::write(&tmp,&text).unwrap();rename(tmp,&output).unwrap();print!("{}",text)}
}
fn main(){fold::run()}
